				const session = ctx.ref
					? await getSessionAtRef(repoPath, ctx.ref, ctx.sessionId)
					: await getSession(repoPath, ctx.sessionId);
				return (session?.files ?? []).map((f) => ({
					path: f.path,
					oldPath: f.oldPath,
					status: f.status,
					additions: f.additions,
					deletions: f.deletions,
