import type {
	Accent,
	AppPlatform,
	BranchInfo,
	ChangedFile,
	CommitFileSelection,
	ContextTab,
	CreateRepoOptions,
	DiffContext,
	DiffData,
	DiffLayout,
	EditorKind,
	FileListLayout,
	GithubAccount,
	LastCommit,
	ManagedStash,
	PRChecksSummary,
	PRReviewComment,
	PRSource,
	PRSummary,
	PrMergedBehavior,
	PublishRepoOptions,
	PushStatus,
	RepoInfo,
	Session,
	SessionSummary,
	TerminalKind,
	UserPrefs,
	ViewMode
} from '@shared/types';
import { WINDOW_BOUNDS } from '@shared/types';
import { diffContextKey } from '@shared/diff-context';
import {
	buildDiscardPatch,
	buildFilteredPatch,
	lineKeySides,
	parseFilePatch,
	stagingLineKey,
	type DiffSide
} from '@shared/diff-staging';
import { DEFAULT_HIDDEN_DIFF_PATTERNS } from '@shared/diff-defer';
import { DEFAULT_HOTKEYS, type Hotkeys } from '@shared/hotkeys';
import { comparePathsVSCodeStyle } from '$lib/utils';

export type SettingsTab = 'accounts' | 'appearance' | 'behavior' | 'app' | 'editor' | 'hotkeys';
